async function logEvent(eventType,detail){try{const uid=typeof currentUser!==`undefined`&&currentUser?currentUser.id:null;await supabaseClient.from(`app_events`).insert({user_id:uid,event_type:eventType,detail:detail?String(detail).slice(0,500):null})}catch(e){}}window.addEventListener(`error`,e=>{logEvent(`error`,`${e.message} (${e.filename}:${e.lineno})`)});window.addEventListener(`unhandledrejection`,e=>{logEvent(`error`,`Promesse rejetée : ${String(e.reason).slice(0,300)}`)});